cards.solution:
const kelasA = ["Ani", "Budi", "Caca"];
const kelasB = ["Dani", "Eka"];
const semuaSiswa = [...kelasA, ...kelasB];
console.log(`Jumlah: ${semuaSiswa.length}`);
console.log(`Terakhir: ${semuaSiswa[semuaSiswa.length - 1]}`);
